/**
 * Русские названия для карточек, импортированных из INCIDB (снимок 2026.09).
 *
 * Ключ — каноническое INCI-имя (inciName, как в prisma/incidb-ingredients.data.ts).
 * INCI остаётся основным идентификатором ингредиента: по нему идёт распознавание
 * составов, уникальный индекс и поиск. Русское название попадает в displayName
 * при сиде (prisma/seed.ts) и показывается рядом с INCI.
 *
 * Файл ведётся вручную и НЕ перезаписывается scripts/import-incidb.py: новые
 * INCI из следующих снимков INCIDB нужно дописывать сюда (сид предупредит,
 * если для карточки перевода нет).
 *
 * Правила перевода: ботаника — «экстракт/масло/воск + часть растения + русское
 * название вида»; синтетические — по русской INCI-номенклатуре (ПЭГ, ППГ,
 * поликватерниум, цетет/лаурет и т. п.); красители — «Краситель CI nnnnn».
 */

